import{_ as e,c as a,o as i,ag as s}from"./chunks/framework.DOxaYS31.js";const h=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),r={name:"guide/getting-started.md"};function l(o,t,n,p,c,d){return i(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Get Grammar Assistant running in 3 simple steps.</p><h2 id="step-1-install" tabindex="-1">Step 1: Install <a class="header-anchor" href="#step-1-install" aria-label="Permalink to &quot;Step 1: Install&quot;">​</a></h2><ol><li>Download the <code>.dmg</code> from <a href="https://github.com/thanhbinhbent/grammar-assistant/releases" target="_blank" rel="noreferrer">Releases page</a></li><li>Drag Grammar Assistant to Applications folder</li><li>Launch the app</li></ol><p><strong>First time?</strong> You may see a security warning:</p><ul><li>Right-click the app → <strong>Open</strong> → Click <strong>Open</strong> in dialog</li><li>This only needs to be done once</li></ul><h2 id="step-2-grant-permission" tabindex="-1">Step 2: Grant Permission <a class="header-anchor" href="#step-2-grant-permission" aria-label="Permalink to &quot;Step 2: Grant Permission&quot;">​</a></h2><p>macOS requires Accessibility permission for the Cmd+Shift+G shortcut:</p><ol><li>Open <strong>System Settings</strong> → <strong>Privacy &amp; Security</strong> → <strong>Accessibility</strong></li><li>Click 🔒 to unlock</li><li>Click <strong>+</strong> and add Grammar Assistant</li><li>Restart the app</li></ol><div class="tip custom-block"><p class="custom-block-title">Why?</p><p>This permission allows the app to:</p><ul><li>Detect when you press Cmd+Shift+G</li><li>Automatically copy your selected text</li><li>Work across all applications</li></ul></div><h2 id="step-3-add-api-key" tabindex="-1">Step 3: Add API Key <a class="header-anchor" href="#step-3-add-api-key" aria-label="Permalink to &quot;Step 3: Add API Key&quot;">​</a></h2><ol><li>Click settings icon (⚙️)</li><li>Choose provider: <ul><li><strong>OpenAI</strong> (<a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">Get key</a>) - Default: gpt-5-nano</li><li><strong>Gemini</strong> (<a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Get key</a>) - Default: gemini-2.5-flash</li></ul></li><li>Paste your API key</li><li>Click Save</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never share your API key publicly!</p></div><h2 id="quick-test" tabindex="-1">Quick Test <a class="header-anchor" href="#quick-test" aria-label="Permalink to &quot;Quick Test&quot;">​</a></h2><ol><li>Select this text: &quot;This are a test sentence with error&quot;</li><li>Press <strong>Cmd+Shift+G</strong></li><li>Choose <strong>Fix Grammar</strong></li><li>Copy and paste the result</li></ol><p>It should say: &quot;This is a test sentence with an error&quot;</p><p>✅ <strong>Working?</strong> You&#39;re ready to go!</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/grammar-assistant/guide/configuration.html">Configuration</a> - Customize settings</li><li><a href="/grammar-assistant/guide/features.html">Features</a> - Learn all enhancement modes</li></ul><p>Happy writing! ✨</p>',20)])])}const u=e(r,[["render",l]]);export{h as __pageData,u as default};
